{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    """Read the orders CSV and return one dict per row, in file order.

    Each dict has the keys "id", "qty" and "price" with int values.
    """
    rows = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for raw in reader:
            rows.append(
                {
                    "id": int(raw["id"]),
                    "qty": int(raw["qty"]),
                    "price": int(raw["price"]),
                }
            )
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """Map each price to the total qty of the rows sharing that price."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": "def report(totals):
    """Render "price:total\\n" lines ordered by price ascending."""
    return "".join(
        "%d:%d\n" % (price, totals[price]) for price in sorted(totals)
    )
"}
